import {nav,categories,topics,foods,inputs,bases,articles} from './data.js';
import {routeUrl} from './routes.js';
import {renderContent,photo,escapeHTML,validRoute} from './content.js';
import {icon} from './icons.js';
const children={food:categories.map(x=>[x.name,'/foods/?category='+x.id]),inputs:[['微生物肥料','/inputs/fertilizer/'],['发酵饲料','/inputs/feed/']],base:[['种植基地','/bases/plant/'],['养殖基地','/bases/animal/']],knowledge:topics.slice(1).map(x=>[x.name,'/knowledge/?topic='+x.id]),events:[['农药残留','/events/?risk=residue'],['重金属','/events/?risk=metal'],['年份索引','/events/']]};
export function header(r){return `<a class="skip-link" href="#main">跳转到正文</a><header class="site-header"><div class="header-inner"><a class="brand" href="/"><span>菌养食材</span></a><button class="menu-toggle" aria-controls="primary-nav" aria-expanded="false" type="button">${icon('menu')}<span>菜单</span></button><nav id="primary-nav" aria-label="主导航">${nav.map(x=>`<div class="nav-item"><a class="nav-link" href="${routeUrl(x.route)}" ${r.section===x.id?'aria-current="page"':''}>${x.label}</a>${children[x.id]?`<details><summary aria-label="展开${x.label}子栏目">${icon('down')}</summary><div class="dropdown">${children[x.id].map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div></details>`:''}</div>`).join('')}</nav><form class="header-search" action="/foods/" role="search"><label class="sr-only" for="header-search">搜索食材</label><input id="header-search" name="search" type="search" placeholder="搜索食材"><button aria-label="搜索食材">${icon('search')}</button></form></div></header>`;}
export function meta(r){const section=nav.find(x=>x.id===r.section);let title=section?.label||'网站介绍',description=({food:'从产品到基地，查看关联的生产与检测资料。',inputs:'了解分类、成分、适用对象与使用资料。',base:'探索生产过程、日常管理与指标监测。',knowledge:'了解微生物、菌养机理、技术方法与检测资料。',events:'按风险类型与年份检索，关注原始信息来源。'})[r.section]||'连接食材、基地与生产记录。',image=({food:'base',inputs:r.query.type==='feed'?'feed':'fertilizer',base:'base',knowledge:'fertilizer',events:'base',about:'base'})[r.section]||'base';const x=({food:foods,input:inputs,base:bases,article:articles})[r.page]?.find(x=>x.id===r.id);if(x){title=x.name||x.title;image=x.image;description=x.description||x.intro||description;}if(r.page==='inputs')title=r.query.type==='feed'?'发酵饲料':'微生物肥料';if(r.page==='about')title='关于菌养食材';if(r.page==='event')title='事件详情版式示意';if(!validRoute(r)){title='这个页面暂时不存在';description='返回首页，继续探索菌养食材。';}return {title,description,image};}
export function subnav(r){let items=children[r.section]||[];if(r.section==='food')items=[['全部食材','/foods/'],...items];if(r.section==='knowledge')items=[['全部文章','/knowledge/'],...items];if(['food','input','base','article','event'].includes(r.page))return '';return items.length?`<nav class="subnav" aria-label="栏目导航"><div class="container">${items.map(([t,u])=>`<a href="${u}" ${((r.page==='inputs'&&u.includes('/'+r.query.type+'/'))||(r.page==='foods'&&(r.query.category?u.endsWith('='+r.query.category):u==='/foods/'))||(r.page==='articles'&&(r.query.topic?u.endsWith('='+r.query.topic):u==='/knowledge/')))?'aria-current="page"':''}>${t}</a>`).join('')}</div></nav>`:'';}
export function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-top"><div><a class="footer-brand" href="/">菌养食材</a><p>了解食材，连接基地与生产记录。</p>${icon('sprout')}</div><nav class="footer-nav" aria-label="页脚导航">${nav.map(x=>`<div><a href="${routeUrl(x.route)}">${x.label}</a>${(children[x.id]||[['网站介绍','/about/']]).slice(0,3).map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div>`).join('')}</nav></div><div class="footer-bottom"><p>界面演示 · 图片、产品、基地及检测资料待补充</p><a href="/about/">网站介绍</a><a href="#main">返回顶部 ↑</a></div></div></footer>`;}
export function renderDocument(route){const r=validRoute(route)?route:{...route,page:'not-found'};const m=meta(r);return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(r.page==='home'?'菌养食材 · 从微生物到日常食材':m.title+' · 菌养食材')}</title><meta name="description" content="${escapeHTML(m.description)}"><meta name="theme-color" content="#234D37"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script type="module" src="/app.js"></script></head><body>${header(r)}<main id="main" tabindex="-1">${r.page==='home'?'':`<section class="column-banner">${photo(m.image,m.title,'',true)}<div><h1>${escapeHTML(m.title)}</h1><p>${escapeHTML(m.description)}</p></div></section><div class="container breadcrumbs"><a href="/">首页</a><span>/</span>${['food','input','base','article','event'].includes(r.page)?`<a href="${routeUrl(nav.find(x=>x.id===r.section)?.route||'#home')}">${nav.find(x=>x.id===r.section)?.label}</a><span>/</span>`:''}<span>${escapeHTML(m.title)}</span></div>${subnav(r)}`}${renderContent(r)}</main>${footer()}</body></html>`;}
